def apply_h(s):
    r = 0.70710678
    return [round(r * (s[0] + s[1]), 4), round(r * (s[0] - s[1]), 4)]

def run_gates(g):
    r = 0.70710678
    a, b = 1.0, 0.0
    for c in g:
        if c == 'X':
            a, b = b, a
        elif c == 'Z':
            b = 0 - b
        elif c == 'H':
            a, b = r * (a + b), r * (a - b)
    return [round(a * a, 4), round(b * b, 4)]

